// Parse the numeric count out of an override segment like 'I12', 'N4', 'I0'
function parseCount(part) {
  if (!part) return 0;
  const m = String(part).match(/\d+/);
  return m ? parseInt(m[0], 10) : 0;
}

// Build an index override component (e.g. 'I8N4'), omitting any zero-length
// I or N segment: 'I0N12' -> 'N12', 'I12N0' -> 'I12', 'I8N4' -> 'I8N4'
function buildIndexComponent(iPart, nPart) {
  const parts = [];
  if (parseCount(iPart) > 0) parts.push(iPart);
  if (parseCount(nPart) > 0) parts.push(nPart);
  return parts.join('');
}

