// Function to get reverse complement of a DNA sequence
function reverseComplement(seq) {
  const complement = {
    'A': 'T', 'T': 'A', 'G': 'C', 'C': 'G',
    'a': 't', 't': 'a', 'g': 'c', 'c': 'g',
    'N': 'N', 'n': 'n'
  };
  return seq.split('').reverse().map(base => complement[base] || base).join('');
}

// Extract parameters from the first item (assuming these are consistent across items)
const read1Cycles = 151;
const read2Cycles = 151;
const index1Cycles = $('When clicking ‘Execute workflow’').first().json.numCycles;
const index2Cycles = $('When clicking ‘Execute workflow’').first().json.numCycles;

// Check if any item has a Lane field
const hasLane = items.some(item => item.json.Lane !== undefined && item.json.Lane !== null && item.json.Lane !== '');

