  // Extract the new fields
  const preparedBy = data.Prepared_By || '';
  const sampleProject = data.Sample_Project || '';
  const requestedBy = data.Requested_By || '';
  const libraryPrepKit = data.Library_Prep_Kit || '';
  const seReads = data.SE_Reads || '';
  const bdsNumber = data.BDS_Number || '';
  const panel = data.Panel || '';

  // Check if this is a TSO library prep kit
  const isTSO = libraryPrepKit && libraryPrepKit.toLowerCase().includes('tso-500');

  let overrideCycles;

  if (isTSO) {
    // For TSO kits: use UMI pattern U7N1 and adjust Y cycles
    const adjustedRead1Cycles = parseInt(read1Cycles) - 8;
    const adjustedRead2Cycles = parseInt(read2Cycles) - 8;
    overrideCycles = `U7N1Y${adjustedRead1Cycles};I${index1Cycles};I${index2Cycles};U7N1Y${adjustedRead2Cycles}`;
  } else {
    // For non-TSO kits: use the original logic with SWAPPED order for index2
    const overrideCycle1I = data['overrideCycle1-I'];
    const overrideCycle2I = data['overrideCycle2-I'];
    const overrideCycle1N = data['overrideCycle1-N'];
    const overrideCycle2N = data['overrideCycle2-N'];

    // Build index1 component (N after I - unchanged)
    const index1Component = (overrideCycle1N && overrideCycle1N !== 'N0') 
      ? `${overrideCycle1I}${overrideCycle1N}` 
      : overrideCycle1I;

    // CHANGE 2: Build index2 component with N BEFORE I (swapped order)
    const index2Component = (overrideCycle2N && overrideCycle2N !== 'N0') 
      ? `${overrideCycle2N}${overrideCycle2I}` 
      : overrideCycle2I;

    overrideCycles = `Y${read1Cycles};${index1Component};${index2Component};Y${read2Cycles}`;
  }

