// Function to normalize text to ASCII
function normalizeToAscii(text) {
  if (typeof text !== 'string') {
    return text;
  }

  // Normalize Unicode characters (NFKD decomposition)
  let normalized = text.normalize('NFKD');

  // Remove diacritical marks and non-ASCII characters
  normalized = normalized.replace(/[\u0300-\u036f]/g, '');

  // Convert Turkish-specific characters manually
  const turkishMap = {
    'ı': 'i', 'İ': 'I',
    'ğ': 'g', 'Ğ': 'G',
    'ü': 'u', 'Ü': 'U',
    'ş': 's', 'Ş': 'S',
    'ö': 'o', 'Ö': 'O',
    'ç': 'c', 'Ç': 'C'
  };

  // Replace Turkish characters
  Object.keys(turkishMap).forEach(char => {
    normalized = normalized.replace(new RegExp(char, 'g'), turkishMap[char]);
  });

  // Keep only ASCII characters
  normalized = normalized.replace(/[^\x00-\x7F]/g, '');

  // Replace non-alphanumeric characters with dashes
  normalized = normalized.replace(/[^a-zA-Z0-9]+/g, '-');

  // Remove leading/trailing dashes
  normalized = normalized.replace(/^-+|-+$/g, '');

  return normalized;
}

